contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address caller, address recipient) public payable {
        // No precondition needed: test for caller identity property
        bool reverted;
        // Simulate calling withdrawAll from `caller` by using low-level call to c with msg.sender = this contract
        // We cannot change msg.sender, so instead we require that the contract was constructed with owner equal to caller
        // Observe revert when run by a non-owner: call c.withdrawAll and catch revert
        // To emulate calls from different senders, we rely on the fact that C.owner is public and was set at construction.
        // Compute whether the provided `caller` equals c.owner()
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        // Now perform the call: if this contract should act as `caller==owner`, then withdrawAll should succeed; otherwise it should revert.
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // General rule: the call reverts iff the caller (msg.sender) is not the owner. Since this contract is the actual msg.sender,
        // we assert that reverted == (address(this) != owner). This holds for the original C but is violated by the mutant.
        assert(reverted == (address(this) != owner));
    }
    receive() external payable { }
}

